function norm(s) {
  return String(s || '')
    .replace(/[\u2012\u2013\u2014\u2015]/g, '-')
    .replace(/[\u2018\u2019\u2032]/g, "'")
    .replace(/[\u201C\u201D\u2033]/g, '"')
    .toLowerCase().replace(/\s+/g, ' ').trim();
}
function mapFor(slug) {
  if (PART1_SLUG_RE.test(slug)) return { label: 'Part 1', scripts: PART1 };
  if (PART2_SLUG_RE.test(slug)) return { label: 'Part 2', scripts: PART2 };
  return null;
}

async function run() {
  await mongoose.connect(MONGODB_URI);
  console.log('Connected.\nMode: ' + (APPLY ? 'APPLY (writing)' : 'DRY RUN (no changes)') + '\n' + '='.repeat(90));

  const candidates = await LiveSession.find({
    sessionType: 'live-course', status: 'scheduled',
    $or: [{ slug: { $regex: PART1_SLUG_RE } }, { slug: { $regex: PART2_SLUG_RE } }]
  }).sort({ scheduledStart: 1 });
  console.log('Found ' + candidates.length + ' scheduled Ethics Table Talk sessions.\n');

  let written = 0, set = 0, drift = 0, unmapped = 0;
  for (const session of candidates) {
    const m = mapFor(session.slug);
    if (!m) continue;
    console.log('\n> ' + session.slug + '  [' + m.label + ']  — ' + (session.agenda?.length || 0) + ' segments');
    if (!session.agenda || !session.agenda.length) { console.log('   ! no agenda rows — run applyEthicsTableTalkAgenda.js first. Skipping.'); continue; }

    const newAgenda = [];
    let changed = false;
    for (const seg of session.agenda) {
      const plain = seg.toObject ? seg.toObject() : { ...seg };
      const entry = m.scripts.find(x => x.order === seg.order);
      if (!entry) { console.log('   ? [' + seg.order + '] "' + seg.title + '" — no script mapped for this order'); unmapped++; newAgenda.push(plain); continue; }
      if (norm(seg.title) !== norm(entry.expectTitle)) {
        console.log('   x DRIFT [' + seg.order + '] stored="' + seg.title + '"  expected="' + entry.expectTitle + '" — SKIPPED'); drift++; newAgenda.push(plain); continue;
      }
      const over = plain.script && plain.script.trim() ? ' (overwriting)' : '';
      console.log('   v [' + seg.order + '] "' + seg.title + '" — ' + entry.script.length + ' chars' + over);
      newAgenda.push({ ...plain, script: entry.script }); set++; changed = true;
    }
    if (APPLY && changed) {
      const res = await LiveSession.updateOne(
        { _id: session._id, sessionType: 'live-course', status: 'scheduled' },
        { $set: { agenda: newAgenda } }
      );
      const fresh = await LiveSession.findById(session._id).lean();
      const filled = (fresh.agenda || []).filter(a => a.script && a.script.trim()).length;
      console.log('   [written] matched=' + res.matchedCount + ' modified=' + res.modifiedCount + '; read-back: ' + filled + ' segments now hold script');
      written++;
    }
  }
  console.log('\n' + '='.repeat(90));
  console.log('Sessions: ' + candidates.length + '   Segments set: ' + set + '   Drift-skipped: ' + drift + '   Unmapped-order: ' + unmapped);
  if (APPLY) console.log('Sessions written: ' + written); else console.log('\nDRY RUN — nothing written. If every segment shows v, re-run with --apply.');
  if (drift > 0) console.log('\n! ' + drift + ' segment(s) skipped on title drift — paste this and I will reconcile the expected titles.');
  await mongoose.disconnect();
}
run().catch(e => { console.error(e); process.exit(1); });
